        words: [{ word: "어김없이", meaning: "毫无例外地，雷打不动地", meaningEn: 'Without fail, religiously' }, { word: "낡은", meaning: "老旧的，陈旧的", meaningEn: 'Rundown, dilapidated' }],
        grammarIds: [],
