        words: [{ word: "문어", meaning: "书面语", meaningEn: 'Written language' }, { word: "기제", meaning: "机制", meaningEn: 'mechanism' }, { word: "억압하다", meaning: "压制，压抑", meaningEn: 'suppression, repression' }],
