/** 按等级分组 */
export function getArticlesByLevel(level: Article['level']): Article[] {
  return readingArticles.filter((a) => a.level === level);
}

/** 按主题分组 */
export function getArticlesByTopic(topic: string): Article[] {
  return readingArticles.filter((a) => a.topic === topic);
}

/** 获取今日阅读推荐 */
// 今日推荐只从「有主打横版图」的 6 篇（6 个主题各自第一篇）里轮换，避免选到无图文章导致 hero 空图/错图
const TODAY_POOL_IDS = [
  'convenience-store-culture', // 文化
  'korean-cafe',               // 生活
  'seoul-subway',              // 旅行
  'korean-education-system',   // 社会
  'kpop-fan-culture',          // KPOP
  'korean-drama-expressions',  // 韩剧
];

export function getTodayArticle(): Article | null {
  const d = new Date();
  const start = new Date(d.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((d.getTime() - start.getTime()) / 86400000);
  const pool = TODAY_POOL_IDS
    .map((id) => readingArticles.find((a) => a.id === id))
    .filter((a): a is Article => !!a && !a.hidden);
  const usable = pool.length ? pool : readingArticles.filter((a) => !a.hidden);
  if (usable.length === 0) return null;
  return usable[dayOfYear % usable.length];
}
